schema_ddl:
CREATE TABLE dipartimenti (
    id_reparto INT PRIMARY KEY,
    nome_dipartimento TEXT NOT NULL,
    budget_annuale NUMERIC(15, 2) CHECK (budget_annuale >= 0)
);

CREATE TABLE dip (
    emp_no INT PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    id_reparto INT NOT NULL REFERENCES dipartimenti(id_reparto),
    data_assunzione DATE NOT NULL DEFAULT CURRENT_DATE,
    stipendio_base NUMERIC(12, 2) CHECK (stipendio_base > 0)
);

CREATE INDEX idx_emp_sorting ON dip (emp_no, data_assunzione);
